<template><view class="m2-page"><view class="library-head"><text class="library-title">会员专属</text><text class="m2-body">所有章节仅VIP可读，不提供免费试读或单章购买。</text><text class="m2-link" @click="vip">查看会员权益 ›</text></view><view v-for="b in items" :key="b.id" class="m2-card book" @click="open(b)"><image class="cover" :src="b.coverUrl||DEFAULT_COVER" mode="aspectFill"/><view class="book-info"><text class="m2-heading">{{b.title}}</text><text class="m2-muted">{{b.authorName}}</text><text class="intro">{{b.intro}}</text><text class="library-tag">仅VIP可读</text></view></view><text v-if="error" class="m2-error" @click="load">{{error}}（点击重试）</text><view v-if="!items.length&&!loading&&!error" class="m2-empty">书库正在准备更多好故事</view><view v-if="loading||items.length<total" class="m2-link m2-center" @click="load">{{loading?'加载中…':'加载更多'}}</view></view></template>
<script>
import {getVipLibrary} from '../../api/vip'
import {DEFAULT_COVER} from '../../utils/cover'
export default{data(){return{items:[],page:1,total:0,loading:false,error:'',DEFAULT_COVER}},onLoad(){this.load()},methods:{vip(){uni.navigateTo({url:'/pages/vip/index'})},open(b){uni.navigateTo({url:'/pages/book/detail?bookId='+b.id})},async load(){if(this.loading)return;this.loading=true;this.error='';try{const d=await getVipLibrary({pageNum:this.page,pageSize:12});this.items.push(...d.records);this.total=Number(d.total);this.page++}catch(e){this.error=e.msg}finally{this.loading=false}}}}
</script><style scoped>.library-head{padding:24rpx;margin-bottom:20rpx}.library-title{font-size:42rpx;color:#765630;font-weight:bold}.book{display:flex;gap:24rpx}.cover{width:140rpx;height:190rpx;border-radius:12rpx;flex-shrink:0}.book-info{flex:1;min-width:0;display:flex;flex-direction:column;gap:12rpx}.intro{font-size:24rpx;line-height:1.6;color:#888;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.library-tag{font-size:20rpx;color:#967449;margin-top:auto}</style>
